def find_path_diagonal(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    queue = deque([(start, [start])])
    visited = set([start])
    while queue:
        current, path = queue.popleft()
        if current == goal:
            return path
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx = current[0] + dx
                ny = current[1] + dy
                if 0 <= nx < len(graph) and 0 <= ny < len(graph[nx]) and ((nx, ny) not in visited) and ((nx, ny) in graph):
                    visited.add((nx, ny))
                    queue.append(((nx, ny), path + [(nx, ny)]))
    return None
