def custom_path_search(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    queue = [[start]]
    visited = set([start])
    if start == goal:
        return [start]
    while queue:
        path = queue.pop(0)
        last_node = path[-1]
        if last_node in visited:
            continue
        for node in graph[last_node]:
            new_path = list(path)
            new_path.append(node)
            if node == goal:
                return new_path
            queue.append(new_path)
            visited.add(node)
        if last_node in visited:
            visited.discard(last_node)
    return None
